final class CostCalculator
{
    public static function eventCost(
        string $unit,
        array $rates,           // map kind => decimal string
        int $tokensIn, int $tokensOut, int $cacheRead, int $cacheWrite,
        ?OffPeakWindow $offPeak,
        int $minuteOfDayUtc,
    ): string {
        if ($unit === 'per_1m_tokens') {
            $base = '0';
            foreach (['input','output','cache_read','cache_write'] as $kind) {
                $tokens = match($kind) {...};
                $base = MoneyMath::add($base, MoneyMath::div(MoneyMath::mul((string)$tokens, (string)($rates[$kind] ?? '0')), '1000000'));
            }
