            $total = $in + $out + $cr + $cw;
            $base = MoneyMath::div(MoneyMath::mul((string)$total, (string)($rates['any'] ?? '0')), '1000000');
        } else { throw ... }
        if ($offPeak !== null && $offPeak->containsMinute($minuteOfDayUtc)) {
            $base = MoneyMath::mul($base, $offPeak->multiplier());
        }
        return MoneyMath::roundHalfUp($base, 6);
    }
}
```

