final class OffPeakWindow
{
    public function __construct(
        private readonly int $startMinute,
        private readonly int $endMinute,
        private readonly string $multiplier,
    ) {}
    public function containsMinute(int $m): bool
    {
        if ($this->startMinute === $this->endMinute) return false; // zero-length window → no discount (assumption)
        if ($this->startMinute < $this->endMinute) {
            return $m >= $this->startMinute && $m < $this->endMinute;
        }
        return $m >= $this->startMinute || $m < $this->endMinute;
    }
    public function multiplier(): string { return $this->multiplier; }
}
```

