final class RatingRunner
{
    public function __construct(private EntityManagerInterface $em, ...) {}

    public function rateAll(): RatingSummary
    {
        $conn = $em->getConnection();
        $conn->beginTransaction();
        try {
            // Fetch unrated events:
            // SELECT e.* FROM usage_events e LEFT JOIN event_ratings r ON r.event_id = e.id WHERE r.id IS NULL ORDER BY e.id
            foreach (...) {
                $row = PriceRowRepository::forModelAt($provider, $model, $ts);
                // model: SELECT id FROM models WHERE provider_code=? AND code=?
                // row: SELECT * FROM price_rows WHERE model_id=? AND valid_from <= ? ORDER BY valid_from DESC LIMIT 1
                if (!$row) { $unrated[] = $event; continue; }
                $providerRow = Provider::byCode($event->provider); // off-peak window
                $cost = CostCalculator::eventCost(...);
                $em->persist(new EventRating($event, $priceRow, $cost, now));
            }
            $em->flush();
            $conn->commit();
        } catch (\Throwable $e) { $conn->rollBack(); throw $e; }
        return new RatingSummary(count($rated), $unrated);
    }
}
```

Use ORM for entities (event, rating) + repositories for simple SQL. That's fine.

