<?php

declare(strict_types=1);

namespace App\Domain;

use ValueError;

/**
 * Точные десятичные вычисления на bcmath: промежуточные значения ведутся
 * с запасом точности (SCALE), округление происходит явно и один раз.
 * float для денег не используется нигде.
 */
final class Money
{
    /** Запас точности для промежуточных расчётов. */
    public const SCALE = 30;

    /** Итоговое число знаков после точки у денег. */
    public const MONEY_SCALE = 6;

    public static function add(string $a, string $b): string
    {
        return bcadd($a, $b, self::SCALE);
    }

    public static function sub(string $a, string $b): string
    {
        return bcsub($a, $b, self::SCALE);
    }

    public static function mul(string $a, string $b): string
    {
        return bcmul($a, $b, self::SCALE);
    }

    public static function div(string $a, string $b): string
    {
        if (bccomp($b, '0', self::SCALE) === 0) {
            throw new ValueError('Деление на ноль');
        }

        return bcdiv($a, $b, self::SCALE);
    }

    public static function cmp(string $a, string $b): int
    {
        return bccomp($a, $b, self::SCALE);
    }

    /**
     * Округление HALF_UP (2.5 -> 3) до заданного числа знаков.
     * Значение ожидается неотрицательным (для стоимостей это инвариант).
     */
    public static function roundHalfUp(string $value, int $scale = self::MONEY_SCALE): string
    {
        if (bccomp($value, '0', self::SCALE) < 0) {
            throw new ValueError('Округление HALF_UP реализовано для неотрицательных значений');
        }

        $factor = bcpow('10', (string) $scale, 0);
        // floor(x * 10^scale + 0.5) == bcdiv(truncate) для x >= 0
        $int = bcdiv(bcadd(bcmul($value, $factor, self::SCALE), '0.5', self::SCALE), '1', 0);

        return bcdiv($int, $factor, $scale);
    }

    /** Возвращает значение с ровно $scale знаками после точки. */
    public static function format(string $value, int $scale = self::MONEY_SCALE): string
    {
        return bcdiv($value, '1', $scale);
    }
}
