CostCalculator:

```php
final class CostCalculator
{
    public const UNIT_PER_KIND = 'per_1m_tokens';
    public const UNIT_UNIFIED = 'per_1m_tokens_unified';
    private const TOKENS_UNIT = '1000000';
    private const PER_KIND = ['input','output','cache_read','cache_write'];

    /**
     * Точная стоимость события: расчёт без округления, в конце — одно
     * HALF_UP-округление до 6 знаков.
     *
     * @param array<string, string> $rates
     */
    public static function eventCost(
        string $unit,
        array $rates,
        int $tokensInput, int $tokensOutput, int $tokensCacheRead, int $tokensCacheWrite,
        ?OffPeakWindow $offPeak,
        int $minuteOfDayUtc,
    ): string {
        if ($unit === self::UNIT_PER_KIND) {
            $base = '0';
            $tokens = ['input' => $tokensInput, 'output' => $tokensOutput, 'cache_read' => $tokensCacheRead, 'cache_write' => $tokensCacheWrite];
            foreach (self::PER_KIND as $kind) {
                if (!isset($rates[$kind])) throw new \DomainException("Отсутствует ставка {$kind} для схемы {$unit}");
                $base = Money::add($base, Money::mul((string) $tokens[$kind], $rates[$kind]));
            }
            $base = Money::div($base, self::TOKENS_UNIT);
        } elseif ($unit === self::UNIT_UNIFIED) {
            if (!isset($rates['any'])) throw new \DomainException('Отсутствует ставка any для схемы per_1m_tokens_unified');
            $total = Money::add(Money::add((string)$tokensInput, (string)$tokensOutput), Money::add((string)$tokensCacheRead, (string)$tokensCacheWrite));
            $base = Money::div(Money::mul($total, $rates['any']), self::TOKENS_UNIT);
        } else {
            throw new \DomainException('Неизвестная схема тарификации: '.$unit);
        }

        if ($offPeak !== null && $offPeak->containsMinute($minuteOfDayUtc)) {
            $base = Money::mul($base, $offPeak->multiplier());
        }

        return Money::roundHalfUp($base);
    }
}
